CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,username TEXT UNIQUE NOT NULL,email TEXT,pass_hash TEXT,tg_id TEXT UNIQUE,balance REAL NOT NULL DEFAULT 0 CHECK(balance>=0),role TEXT NOT NULL DEFAULT 'user',banned INTEGER DEFAULT 0,created DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS transactions(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),type TEXT NOT NULL,amount REAL NOT NULL,balance_after REAL NOT NULL,note TEXT,ref TEXT,created DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS services(id INTEGER PRIMARY KEY,category TEXT NOT NULL,name TEXT NOT NULL,description TEXT DEFAULT '',price REAL NOT NULL,cost REAL DEFAULT 0,min_qty INTEGER NOT NULL,max_qty INTEGER NOT NULL,delivery TEXT DEFAULT '',supplier_service TEXT,enabled INTEGER DEFAULT 1);
CREATE UNIQUE INDEX IF NOT EXISTS ux_ss ON services(supplier_service);
CREATE TABLE IF NOT EXISTS smm_orders(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),service_id INTEGER NOT NULL REFERENCES services(id),link TEXT NOT NULL,quantity INTEGER NOT NULL,charge REAL NOT NULL,status TEXT NOT NULL DEFAULT 'Pending',supplier_order TEXT,remains INTEGER DEFAULT 0,refunded REAL DEFAULT 0,error TEXT,created DATETIME DEFAULT CURRENT_TIMESTAMP,updated DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS products(id INTEGER PRIMARY KEY,category TEXT NOT NULL,name TEXT NOT NULL,description TEXT DEFAULT '',image TEXT DEFAULT '',price REAL NOT NULL,delivery_type TEXT NOT NULL DEFAULT 'auto',stock INTEGER DEFAULT 0,enabled INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS inventory(id INTEGER PRIMARY KEY,product_id INTEGER NOT NULL REFERENCES products(id) ON DELETE CASCADE,secret TEXT NOT NULL,sold_order INTEGER);
CREATE TABLE IF NOT EXISTS digital_orders(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),product_id INTEGER NOT NULL,product_name TEXT,quantity INTEGER DEFAULT 1,price REAL NOT NULL,status TEXT NOT NULL,delivery TEXT,note TEXT,created DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS payments(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),amount REAL NOT NULL,bonus REAL DEFAULT 0,method TEXT DEFAULT 'ABA KHQR',ref TEXT UNIQUE NOT NULL,provider_ref TEXT UNIQUE,status TEXT NOT NULL DEFAULT 'pending',created DATETIME DEFAULT CURRENT_TIMESTAMP,paid_at DATETIME);
CREATE TABLE IF NOT EXISTS promos(id INTEGER PRIMARY KEY,code TEXT UNIQUE NOT NULL,title TEXT,bonus_percent REAL NOT NULL,active INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS tickets(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),subject TEXT NOT NULL,status TEXT DEFAULT 'open',created DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ticket_msgs(id INTEGER PRIMARY KEY,ticket_id INTEGER NOT NULL REFERENCES tickets(id),user_id INTEGER NOT NULL,is_admin INTEGER DEFAULT 0,body TEXT NOT NULL,created DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS notifications(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL,text TEXT NOT NULL,created DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT);
CREATE TABLE IF NOT EXISTS logs(id INTEGER PRIMARY KEY,user_id INTEGER,action TEXT,detail TEXT,created DATETIME DEFAULT CURRENT_TIMESTAMP);
